<?php require __DIR__.'/includes/bootstrap.php'; $_SESSION['cart']=$_SESSION['cart']??[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]);elseif(isset($_POST['product_id'])){$id=(int)$_POST['product_id'];$qty=max(1,min(99,(int)($_POST['qty']??1)));$s=$pdo->prepare('SELECT id FROM products WHERE id=? AND active=1');$s->execute([$id]);if($s->fetch())$_SESSION['cart'][$id]=min(99,($_SESSION['cart'][$id]??0)+$qty);}header('Location: cart.php');exit;}
$items=[];$total=0;if($_SESSION['cart']){$ids=array_keys($_SESSION['cart']);$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE active=1 AND id IN ($marks)");$s->execute($ids);foreach($s as $p){$p['qty']=$_SESSION['cart'][$p['id']];$p['subtotal']=$p['qty']*$p['price'];$total+=$p['subtotal'];$items[]=$p;}}
$page_title='سلة التسوق';require __DIR__.'/includes/header.php'; ?><main class="container"><h1 class="gold">سلة التسوق</h1><?php if(!$items): ?><div class="panel empty">سلتك فارغة حالياً <p><a class="btn" href="index.php">تصفح المنتجات</a></p></div><?php else: ?><div class="panel table-wrap"><table><tr><th>المنتج</th><th>السعر</th><th>الكمية</th><th>الإجمالي</th><th></th></tr><?php foreach($items as $p): ?><tr><td><?=e($p['name'])?></td><td><?=money($p['price'])?></td><td><?= (int)$p['qty']?></td><td><?=money($p['subtotal'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="btn secondary" name="remove" value="<?=(int)$p['id']?>">حذف</button></form></td></tr><?php endforeach; ?></table><h2 class="price">الإجمالي: <?=money($total)?></h2><a class="btn" href="checkout.php">إتمام الطلب</a></div><?php endif; ?></main><?php require __DIR__.'/includes/footer.php'; ?>
